"""Pure contracts and evidence analysis for controlled request baselines."""

from __future__ import annotations

import base64
import hashlib
from datetime import datetime
from enum import StrEnum
from typing import Literal, Self
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field, model_validator

from transport_matters.canonicalization import canonical_digest
from transport_matters.request_inventory import (
    RequestInventory,
    RequestJsonNode,
    RequestStringLeaf,
    build_request_inventory,
    observe_request_json,
)


class ProbeLabel(StrEnum):
    A1 = "a1"
    B = "b"
    A2 = "a2"


class EvidenceKind(StrEnum):
    STABLE = "stable"
    PROMPT_DERIVED = "prompt-derived"
    SESSION_GENERATED = "session-generated"
    MODEL_DEPENDENT = "model-dependent"
    STRUCTURALLY_OPTIONAL = "structurally-optional"
    UNKNOWN = "unknown"


class DriftOutcome(StrEnum):
    EXACT = "exact"
    COMPATIBLE = "compatible-drift"
    BREAKING = "breaking-drift"
    INSUFFICIENT = "insufficient-evidence"


class ControlledPrompts(BaseModel):
    model_config = ConfigDict(frozen=True)

    prompt_a: str = Field(min_length=1)
    prompt_b: str = Field(min_length=1)

    @model_validator(mode="after")
    def require_distinct_prompts(self) -> Self:
        if self.prompt_a == self.prompt_b:
            raise ValueError("controlled prompts must be distinct")
        return self


class BaselineCell(BaseModel):
    model_config = ConfigDict(frozen=True)

    harness: str = Field(min_length=1)
    provider: str = Field(min_length=1)
    harness_version: str | None
    launch_model: str = Field(min_length=1)
    wire_model: str = Field(min_length=1)
    request_shape: Literal["first-turn"] = "first-turn"


class TranscriptEvidence(BaseModel):
    model_config = ConfigDict(frozen=True)

    path: str = Field(min_length=1)
    bytes_base64: str
    sha256: str = Field(pattern=r"^[0-9a-f]{64}$")

    @model_validator(mode="after")
    def validate_bytes(self) -> Self:
        try:
            snapshot = base64.b64decode(self.bytes_base64, validate=True)
        except ValueError as exc:
            raise ValueError("transcript evidence is not valid base64") from exc
        if hashlib.sha256(snapshot).hexdigest() != self.sha256:
            raise ValueError("transcript digest does not match embedded bytes")
        return self


class ProbeEvidence(BaseModel):
    model_config = ConfigDict(frozen=True)

    label: ProbeLabel
    delivery_id: UUID
    prompt_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    run_id: str = Field(min_length=1)
    exchange_id: str = Field(min_length=1)
    correlation_method: Literal["unique-prompt"]
    raw_request_base64: str
    raw_request_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    inventory: RequestInventory
    raw_nodes: tuple[RequestJsonNode, ...]
    normalized_request: dict[str, object]
    transcripts: tuple[TranscriptEvidence, ...] = Field(min_length=1)

    @model_validator(mode="after")
    def validate_raw_evidence(self) -> Self:
        try:
            raw = base64.b64decode(self.raw_request_base64, validate=True)
        except ValueError as exc:
            raise ValueError("raw request evidence is not valid base64") from exc
        digest = hashlib.sha256(raw).hexdigest()
        if digest != self.raw_request_sha256:
            raise ValueError("raw request digest does not match embedded bytes")
        if digest != self.inventory.raw_sha256:
            raise ValueError("raw request digest does not match request inventory")
        if observe_request_json(raw) != self.raw_nodes:
            raise ValueError("raw request nodes do not match embedded bytes")
        rebuilt = build_request_inventory(raw, capture=self.inventory.capture)
        expected_leaves = tuple((leaf.pointer, leaf.value, leaf.sha256) for leaf in rebuilt.leaves)
        actual_leaves = tuple(
            (leaf.pointer, leaf.value, leaf.sha256) for leaf in self.inventory.leaves
        )
        if expected_leaves != actual_leaves:
            raise ValueError("request inventory leaves do not match embedded bytes")
        return self


class JsonNodeObservation(BaseModel):
    model_config = ConfigDict(frozen=True)

    pointer: str
    kinds: tuple[str, ...]
    present_in: tuple[ProbeLabel, ...]


class PointerEvidence(BaseModel):
    model_config = ConfigDict(frozen=True)

    pointer: str
    value_sha256_by_probe: dict[ProbeLabel, str]
    presence_by_probe: dict[ProbeLabel, bool]
    tm_ir_sections: tuple[str, ...]
    kinds: tuple[str, ...]
    classifications: tuple[EvidenceKind, ...]
    reason: str


class AbaAnalysis(BaseModel):
    model_config = ConfigDict(frozen=True)

    observed_schema: tuple[JsonNodeObservation, ...]
    pointer_evidence: tuple[PointerEvidence, ...]
    static_fingerprint: str
    repeat_a_outcome: DriftOutcome
    model_dependence_assessed: Literal[False] = False


class BaselineComparison(BaseModel):
    model_config = ConfigDict(frozen=True)

    outcome: DriftOutcome
    reasons: tuple[str, ...]


class BaselineBundle(BaseModel):
    model_config = ConfigDict(frozen=True)

    artifact_schema_version: Literal[1]
    bundle_id: UUID
    generated_at: datetime
    source_commit: str = Field(pattern=r"^[0-9a-f]{40}$")
    cell: BaselineCell
    prompts: ControlledPrompts
    probes: tuple[ProbeEvidence, ProbeEvidence, ProbeEvidence]
    observed_schema: tuple[JsonNodeObservation, ...]
    pointer_evidence: tuple[PointerEvidence, ...]
    static_fingerprint: str = Field(pattern=r"^[0-9a-f]{64}$")
    repeat_a_outcome: DriftOutcome
    reference_bundle_id: UUID | None
    reference_outcome: DriftOutcome
    reference_reasons: tuple[str, ...]
    model_dependence_assessed: Literal[False] = False

    @model_validator(mode="after")
    def validate_probe_contract(self) -> Self:
        labels = tuple(probe.label for probe in self.probes)
        if labels != (ProbeLabel.A1, ProbeLabel.B, ProbeLabel.A2):
            raise ValueError("baseline bundle probes must be ordered a1, b, a2")
        expected_prompts = (self.prompts.prompt_a, self.prompts.prompt_b, self.prompts.prompt_a)
        for probe, prompt in zip(self.probes, expected_prompts, strict=True):
            if probe.prompt_sha256 != hashlib.sha256(prompt.encode()).hexdigest():
                raise ValueError(f"{probe.label} prompt digest does not match controlled plan")
            capture = probe.inventory.capture
            if (
                capture.harness != self.cell.harness
                or capture.provider != self.cell.provider
                or capture.harness_version != self.cell.harness_version
                or capture.model != self.cell.wire_model
            ):
                raise ValueError(f"{probe.label} provenance does not match baseline cell")
        if self.reference_bundle_id is None and self.reference_outcome != DriftOutcome.INSUFFICIENT:
            raise ValueError("bootstrap bundle reference outcome must be insufficient evidence")
        if not self.reference_reasons:
            raise ValueError("baseline reference comparison must record a reason")
        return self


def classify_aba(
    *,
    prompts: ControlledPrompts,
    probes: tuple[ProbeEvidence, ProbeEvidence, ProbeEvidence],
) -> AbaAnalysis:
    """Classify one controlled single model observation without overclaiming."""

    _require_probe_order(probes)
    nodes_by_probe = {
        probe.label: {node.pointer: node for node in probe.raw_nodes} for probe in probes
    }
    leaves_by_probe = {
        probe.label: {leaf.pointer: leaf for leaf in probe.inventory.leaves} for probe in probes
    }
    pointers = sorted({pointer for nodes in nodes_by_probe.values() for pointer in nodes})
    schema: list[JsonNodeObservation] = []
    evidence: list[PointerEvidence] = []
    for pointer in pointers:
        present = tuple(label for label in ProbeLabel if pointer in nodes_by_probe[label])
        nodes = {label: nodes_by_probe[label][pointer] for label in present}
        schema.append(
            JsonNodeObservation(
                pointer=pointer,
                kinds=tuple(sorted({node.kind for node in nodes.values()})),
                present_in=present,
            )
        )
        evidence.append(
            _classify_pointer(
                pointer=pointer,
                prompts=prompts,
                nodes=nodes,
                leaves_by_probe=leaves_by_probe,
            )
        )
    static_records = [
        {
            "pointer": item.pointer,
            "sha256": next(iter(item.value_sha256_by_probe.values())),
            "kinds": item.kinds,
        }
        for item in evidence
        if item.classifications == (EvidenceKind.STABLE,)
    ]
    return AbaAnalysis(
        observed_schema=tuple(schema),
        pointer_evidence=tuple(evidence),
        static_fingerprint=canonical_digest(static_records),
        repeat_a_outcome=_repeat_a_outcome(tuple(evidence)),
    )


def compare_baseline_bundles(
    reference: BaselineBundle,
    candidate: BaselineBundle,
) -> BaselineComparison:
    """Compare two observations of the same provider neutral cell."""

    reference_key = (
        reference.cell.harness,
        reference.cell.provider,
        reference.cell.launch_model,
        reference.cell.request_shape,
    )
    candidate_key = (
        candidate.cell.harness,
        candidate.cell.provider,
        candidate.cell.launch_model,
        candidate.cell.request_shape,
    )
    if reference_key != candidate_key:
        return BaselineComparison(
            outcome=DriftOutcome.INSUFFICIENT,
            reasons=("baseline cell coordinates do not match",),
        )
    if (
        reference.static_fingerprint == candidate.static_fingerprint
        and reference.observed_schema == candidate.observed_schema
    ):
        return BaselineComparison(
            outcome=DriftOutcome.EXACT,
            reasons=("observed schema and stable baseline fingerprint match",),
        )
    if reference.static_fingerprint != candidate.static_fingerprint:
        return BaselineComparison(
            outcome=DriftOutcome.BREAKING,
            reasons=("stable baseline fingerprint changed",),
        )
    reference_schema = {item.pointer: item for item in reference.observed_schema}
    candidate_evidence = {item.pointer: item for item in candidate.pointer_evidence}
    changed_pointers = {
        pointer
        for pointer in set(reference_schema) | {item.pointer for item in candidate.observed_schema}
        if reference_schema.get(pointer)
        != next((item for item in candidate.observed_schema if item.pointer == pointer), None)
    }
    allowed = {
        EvidenceKind.PROMPT_DERIVED,
        EvidenceKind.SESSION_GENERATED,
        EvidenceKind.STRUCTURALLY_OPTIONAL,
        EvidenceKind.STABLE,
    }
    if changed_pointers and all(
        pointer in candidate_evidence
        and set(candidate_evidence[pointer].classifications) <= allowed
        for pointer in changed_pointers
    ):
        return BaselineComparison(
            outcome=DriftOutcome.COMPATIBLE,
            reasons=("shape changes remain within demonstrated nonstatic evidence",),
        )
    return BaselineComparison(
        outcome=DriftOutcome.INSUFFICIENT,
        reasons=("changed request evidence is not classified strongly enough",),
    )


def _require_probe_order(
    probes: tuple[ProbeEvidence, ProbeEvidence, ProbeEvidence],
) -> None:
    labels = tuple(probe.label for probe in probes)
    if labels != (ProbeLabel.A1, ProbeLabel.B, ProbeLabel.A2):
        raise ValueError("controlled probes must be ordered a1, b, a2")


def _classify_pointer(
    *,
    pointer: str,
    prompts: ControlledPrompts,
    nodes: dict[ProbeLabel, RequestJsonNode],
    leaves_by_probe: dict[ProbeLabel, dict[str, RequestStringLeaf]],
) -> PointerEvidence:
    digests = {label: node.sha256 for label, node in nodes.items()}
    presence = {label: label in nodes for label in ProbeLabel}
    kinds = tuple(sorted({node.kind for node in nodes.values()}))
    classifications: list[EvidenceKind] = []
    reasons: list[str] = []
    unique_digests = set(digests.values())
    if len(nodes) >= 2 and len(unique_digests) == 1:
        classifications.append(EvidenceKind.STABLE)
        reasons.append("all observed values match")
    elif _direct_prompt_pattern(pointer, prompts, digests, leaves_by_probe):
        classifications.append(EvidenceKind.PROMPT_DERIVED)
        reasons.append("A values contain prompt A and B contains prompt B")
    elif _session_derived(pointer, leaves_by_probe):
        classifications.append(EvidenceKind.SESSION_GENERATED)
        reasons.append("request inventory marks the value as session derived")
    else:
        classifications.append(EvidenceKind.UNKNOWN)
        reasons.append("controlled probes do not prove the value source")
    if len(nodes) != len(ProbeLabel):
        classifications.append(EvidenceKind.STRUCTURALLY_OPTIONAL)
        reasons.append("pointer presence varies across probes")
    sections = tuple(
        sorted(
            {
                leaf.tm_ir_section
                for leaves in leaves_by_probe.values()
                if (leaf := leaves.get(pointer)) is not None and leaf.tm_ir_section is not None
            }
        )
    )
    return PointerEvidence(
        pointer=pointer,
        value_sha256_by_probe=digests,
        presence_by_probe=presence,
        tm_ir_sections=sections,
        kinds=kinds,
        classifications=tuple(classifications),
        reason="; ".join(reasons),
    )


def _direct_prompt_pattern(
    pointer: str,
    prompts: ControlledPrompts,
    digests: dict[ProbeLabel, str],
    leaves_by_probe: dict[ProbeLabel, dict[str, RequestStringLeaf]],
) -> bool:
    if set(digests) != set(ProbeLabel):
        return False
    if not (
        digests[ProbeLabel.A1] == digests[ProbeLabel.A2]
        and digests[ProbeLabel.B] != digests[ProbeLabel.A1]
    ):
        return False
    values: dict[ProbeLabel, str | None] = {
        label: leaf.value if (leaf := leaves_by_probe[label].get(pointer)) is not None else None
        for label in ProbeLabel
    }
    a1_value = values[ProbeLabel.A1]
    b_value = values[ProbeLabel.B]
    a2_value = values[ProbeLabel.A2]
    return (
        isinstance(a1_value, str)
        and isinstance(b_value, str)
        and isinstance(a2_value, str)
        and prompts.prompt_a in a1_value
        and prompts.prompt_b in b_value
        and prompts.prompt_a in a2_value
    )


def _session_derived(
    pointer: str,
    leaves_by_probe: dict[ProbeLabel, dict[str, RequestStringLeaf]],
) -> bool:
    leaves = [leaves.get(pointer) for leaves in leaves_by_probe.values()]
    present = [leaf for leaf in leaves if leaf is not None]
    return bool(present) and all(leaf.provenance.kind == "session-derived" for leaf in present)


def _repeat_a_outcome(evidence: tuple[PointerEvidence, ...]) -> DriftOutcome:
    changed = [
        item
        for item in evidence
        if item.presence_by_probe[ProbeLabel.A1] != item.presence_by_probe[ProbeLabel.A2]
        or (
            not set(item.kinds) <= {"array", "object"}
            and item.value_sha256_by_probe.get(ProbeLabel.A1)
            != item.value_sha256_by_probe.get(ProbeLabel.A2)
        )
    ]
    if not changed:
        return DriftOutcome.EXACT
    allowed = {EvidenceKind.SESSION_GENERATED, EvidenceKind.STRUCTURALLY_OPTIONAL}
    if all(set(item.classifications) <= allowed for item in changed):
        return DriftOutcome.COMPATIBLE
    return DriftOutcome.INSUFFICIENT

