        keys = [key for key, _ in pairs]
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate decoded object key prevents unique JSON Pointer identity")
        return _JsonObject(tuple(pairs))

    def reject_non_finite_number(value: str) -> object:
        raise ValueError(f"request_raw contains non-JSON numeric constant {value!r}")

